/**
 * David Anointed
 * --------------
 * Samuel anoints David the youngest son of Jesse in Bethlehem, and the Spirit of the Lord comes upon him from that day. Stage: a Bethlehem hillside at golden hour, a boy among his brothers, a horn of oil, a shepherd's crook; the last son, the first light on a new king.
 *
 * Palette 0x1a2a1a → 0x060402 · light: dawn · hero: horn
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./samuel-kit.js.
 */

import { THREE, createScene, cityGate, house, column, throne, sheep, jar, horn, person, birds } from './samuel-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1267016791, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [20, 0, -58], { name: 'city', r: [0, 0.18, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x142014 });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x111b11 });

    /* flock: sheep grazing */
    sheep(W, group, -0.5, 0, 9.4, W.r() * 6, 1.02);
    sheep(W, group, -15.9, 0, 6.2, W.r() * 6, 1.12);
    sheep(W, group, 3.0, 0, 5.2, W.r() * 6, 0.95);
    sheep(W, group, 12.0, 0, 8.9, W.r() * 6, 0.92);
    sheep(W, group, -3.9, 0, -6.9, W.r() * 6, 1.06);
    sheep(W, group, -2.6, 0, 4.1, W.r() * 6, 0.97);
    sheep(W, group, -3.3, 0, -5.9, W.r() * 6, 1.06);

    jar(W, group, -1.6, 0, -3.8, );

    /* hero: the horn */
    horn(W, group, 0, 1.2, 0, 1.3, { color: 0x172617 });
    W.disc([0, 4, -10], 4, 0x223722, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.30, s: 1.03 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.31, s: 1.15 });
    person(W, group, [1, 0, -5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.47, s: 1.14 });

    /* birds: slow circles high above */
    birds(W, group, 6, 55, { y: 26 });

    return W.finish();
}

export default { build };
